CREATE TABLE tentative_bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,customer_id uuid,service_id uuid NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','DECLINED')),candidates jsonb NOT NULL CHECK(jsonb_array_length(candidates) BETWEEN 1 AND 3),approved_booking_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE SET NULL,FOREIGN KEY(tenant_id,service_id) REFERENCES services(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,approved_booking_id) REFERENCES bookings(tenant_id,id) ON DELETE SET NULL,UNIQUE(tenant_id,id));
CREATE TABLE customer_memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,customer_id uuid NOT NULL,name text NOT NULL,remaining_sessions integer NOT NULL CHECK(remaining_sessions>=0),expires_at timestamptz,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE CASCADE,UNIQUE(tenant_id,id));CREATE INDEX memberships_customer_idx ON customer_memberships(tenant_id,customer_id,active);
CREATE TABLE membership_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,membership_id uuid NOT NULL,booking_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,membership_id) REFERENCES customer_memberships(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id) ON DELETE CASCADE,UNIQUE(tenant_id,membership_id,booking_id));
CREATE TABLE external_booking_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,provider text NOT NULL,external_id text NOT NULL,booking_id uuid,staff_id uuid,resource_id uuid,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id) ON DELETE SET NULL,FOREIGN KEY(tenant_id,staff_id) REFERENCES staff_profiles(tenant_id,id) ON DELETE SET NULL,FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id) ON DELETE SET NULL,UNIQUE(tenant_id,provider,external_id));CREATE INDEX external_booking_time_idx ON external_booking_events(tenant_id,starts_at,ends_at);
CREATE TABLE booking_integrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,booking_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('MEETING','ACCESS')),provider text NOT NULL,external_id text NOT NULL,secret_ref text,public_ref text,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id) ON DELETE CASCADE,UNIQUE(tenant_id,kind,provider,external_id));
CREATE TABLE advanced_booking_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,event_type text NOT NULL,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
